// Проверка подписи RAHTIS на входящем фото весового талона.
//
// Платформа подписывает исходящий запрос тем же секретом, которым мы
// подписываем обратные: HMAC-SHA256 на AGENT_WEBHOOK_SECRET от строки
// `${timestamp}.${body}`, заголовок x-rahtis-signature вида sha256=<hex>.
//
// Без проверки вебхук открыт: кто узнал адрес, тот будет гонять
// OpenAI за наш счёт.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.AGENT_WEBHOOK_SECRET) SECRET = $vars.AGENT_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('AGENT_WEBHOOK_SECRET не задан: создайте переменную в n8n или впишите значение в SECRET.');
const secret = SECRET;

// Сырое тело подписи. n8n отдаёт его по-разному: строкой, буфером,
// разобранным объектом, а при rawBody иногда двоичным вложением. Подпись
// считается от БАЙТОВ, которые прислала платформа, поэтому читаем все
// формы, а разбор JSON оставляем на потом.
function rawBody() {
  try {
    const bin = $input.item.binary;
    if (bin && bin.data && bin.data.data) return Buffer.from(bin.data.data, 'base64').toString('utf8');
  } catch (e) {}
  const b = $json.body;
  if (typeof b === 'string') return b;
  if (Buffer.isBuffer(b)) return b.toString('utf8');
  if (b && b.type === 'Buffer' && Array.isArray(b.data)) return Buffer.from(b.data).toString('utf8');
  return JSON.stringify(b || {});
}
const raw = rawBody();
const ts = $json.headers['x-rahtis-timestamp'] || '';
const given = $json.headers['x-rahtis-signature'] || '';

// Окно 300 секунд: перехваченный запрос нельзя повторить назавтра.
const age = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
const fresh = Number.isFinite(age) && age <= 300;

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(given);
const signed = a.length === b.length && crypto.timingSafeEqual(a, b);

let p = {};
try { p = JSON.parse(raw); } catch (e) { try { p = (typeof $json.body === 'object' && $json.body) || {}; } catch (e2) { p = {}; } }

const MIMES = ['image/jpeg', 'image/png', 'image/webp'];
const mime = MIMES.includes(p.mime) ? p.mime : 'image/jpeg';
const data = typeof p.data_base64 === 'string' ? p.data_base64 : '';
return [{
  json: {
    // Фото не больше ~10 МБ (в base64 — ~14 МБ строки).
    ok: signed && fresh && data.length > 0 && data.length < 15000000,
    why: signed ? (fresh ? null : 'stale') : 'signature',
    mime,
    data_base64: data,
    plates: Array.isArray(p.plates) ? p.plates.filter((x) => typeof x === 'string').slice(0, 300) : [],
    expected_plates: Array.isArray(p.expected_plates) ? p.expected_plates.filter((x) => typeof x === 'string').slice(0, 5) : [],
    country: typeof p.country === 'string' ? p.country.slice(0, 2) : 'FI',
  },
}];

// Запрос к OpenAI: поля весового талона (punnituskuitti / vaakakuitti / vågsedel) с фото.
// Ответ — строго по схеме; сайт пересчитывает веса из напечатанных строк
// сам (src/lib/weighTicket/reading.ts) и показывает человеку на проверку.
const MATERIALS = ['170504', '170506', '170503', '170107', '170302', '170904', 'SORA', 'MURSKE', 'HIEKKA', 'MULTA', 'LOUHE'];
const system = [
  'You read photos of weighing tickets from Nordic and Baltic scales (Finnish: punnituskuitti, vaakakuitti, punnitustosite; Swedish: vågsedel, vägningskvitto; Norwegian: veieseddel; Estonian: kaalumistõend). They come from earthworks: soil, gravel, crushed rock and construction waste hauled by tipper trucks.',
  'Read only what is printed or clearly handwritten on the ticket. Never invent a value: if it is missing, cut off or unreadable, use null and say so in notes.',
  'ticket_number: the ticket or weighing number (Kuitti nro, Punnitus nro, Tosite, Nro, Vågsedel nr, Kvitto nr), exactly as printed without the label.',
  'weighed_at: the date and time of the (last) weighing as YYYY-MM-DDTHH:MM in local time, or YYYY-MM-DD if there is no time; null if absent. Finnish and Swedish dates are day first (3.11.2026 = 2026-11-03).',
  'plates: every vehicle and trailer registration number on the ticket (Rek.nro, Rekisterinumero, Ajoneuvo, Auto, Perävaunu, Reg.nr, Fordon, Släp), as printed, truck first. Known plates of this company: ' + ($json.plates.join(', ') || 'none') + '. Plates expected on this trip: ' + ($json.expected_plates.join(', ') || 'unknown') + '. Report what the ticket says even if it differs from these.',
  'Weights: gross = Brutto / Kokonaispaino / Bruttovikt / Kokonaismassa (the loaded vehicle); tare = Tara / Taara / Omapaino / Tomvikt; net = Netto / Nettopaino / Nettovikt / Kuorma. gross_text, tare_text and net_text are the numbers EXACTLY as printed, with the original separators (for example "24 560", "24.560", "24,56"), without the unit; null if absent.',
  'unit: the unit printed next to the weights: "kg" or "t" (tonnes, tn, tonnia); null if none is printed.',
  'gross_kg, tare_kg and net_kg: the same weights converted to whole kilograms. In tonnes the comma or point is the decimal separator (24,56 t = 24560 kg). In kilograms a point or space between groups of three digits is a thousands separator (24.560 kg = 24560 kg). If no unit is printed, values under 100 are tonnes and values of 1000 or more are kilograms. Do not compute a missing value from the other two; leave it null.',
  'material: the material or product as printed (Tuote, Materiaali, Laji, Jätelaji, Produkt, Material), short; null if absent. material_code: the closest of these codes, or null if none fits: 170504 = clean soil and stones (maa-aines, kivennäismaa, puhdas maa, savi, moreeni), 170506 = dredging spoil (ruoppausmassa), 170503 = contaminated soil (pilaantunut maa), 170107 = concrete or brick waste (betoni, tiili), 170302 = asphalt waste (asfaltti), 170904 = mixed construction waste (sekajäte, rakennusjäte), SORA = gravel, MURSKE = crushed rock (murske, kalliomurske), HIEKKA = sand, MULTA = topsoil or mould (multa, kasvualusta), LOUHE = blasted rock (louhe).',
  'scale_name: the name of the scale site or company that issued the ticket (the header, for example "HSY Ämmässuo" or "NCC Mäntsälä"), with the town if printed; null if absent. customer: the customer or site name if printed, else null.',
  'confidence: "high" if all printed values are clearly legible, "medium" if some are uncertain, "low" if the photo is blurred, cut off or not a weighing ticket. notes: one short English sentence about anything uncertain (for example a smudged digit or two weighings on one ticket), or null.',
  'Country of the carrier: ' + $json.country + '.',
].join(' ');

const num = { type: ['integer', 'null'] };
const str = { type: ['string', 'null'] };
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['ticket_number', 'weighed_at', 'plates', 'gross_text', 'tare_text', 'net_text', 'unit', 'gross_kg', 'tare_kg', 'net_kg', 'material', 'material_code', 'scale_name', 'customer', 'confidence', 'notes'],
  properties: {
    ticket_number: str,
    weighed_at: str,
    plates: { type: 'array', items: { type: 'string' } },
    gross_text: str,
    tare_text: str,
    net_text: str,
    unit: { type: ['string', 'null'], enum: ['kg', 't', null] },
    gross_kg: num,
    tare_kg: num,
    net_kg: num,
    material: str,
    material_code: { type: ['string', 'null'], enum: [...MATERIALS, null] },
    scale_name: str,
    customer: str,
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    notes: str,
  },
};

const user = [
  { type: 'image_url', image_url: { url: 'data:' + $json.mime + ';base64,' + $json.data_base64, detail: 'high' } },
  { type: 'text', text: 'Read this weighing ticket.' },
];

return [{ json: { payload: JSON.stringify({
  // gpt-4.1 и 4o уходят 14.01.2027; у gpt-6-luna нет temperature, усилие — low (талон короткий, ответ за секунды).
  model: 'gpt-6-luna',
  reasoning_effort: 'low',
  response_format: { type: 'json_schema', json_schema: { name: 'weigh_ticket', strict: true, schema } },
  messages: [ { role: 'system', content: system }, { role: 'user', content: user } ],
}) } }];

// Ответ OpenAI → то, что ждёт сайт. Поля сайт проверит и пересчитает сам (src/lib/weighTicket/reading.ts).
let out = { ok: false, ticket: null };
try {
  const data = JSON.parse($json.choices[0].message.content);
  out = { ok: !!data && typeof data === 'object', ticket: data };
} catch (e) {
  out = { ok: false, ticket: null, detail: ($json.error && $json.error.message) || 'parse' };
}
return [{ json: out }];
